            "explicit_text_reference": "Preferred: run the bundled script (handles gh field drift and job-log fallbacks):",
            "invocation": "python \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number-or-url>\"",
            "interface": {
              "entrypoint": "main()",
              "parameters": {
                "--repo": {
                  "default": ".",
                  "description": "Path inside the target Git repository."
                },
                "--pr": {
                  "default": null,
                  "description": "PR number or URL (defaults to current branch PR)."
                },
                "--max-lines": {
